var DT_BAYER4 = [
  [ 0,  8,  2, 10],
  [12,  4, 14,  6],
  [ 3, 11,  1,  9],
  [15,  7, 13,  5]
];
function dtGray(r, g, b){ return 0.299*r + 0.587*g + 0.114*b; }
function dtThreshold(gray, w, h){
  var out = [];
  for(var i=0;i<w*h;i++) out.push(gray[i] >= 128 ? 255 : 0);
  return out;
}
function dtBayer(gray, w, h){
  var out = [];
  for(var y=0;y<h;y++){
    for(var x=0;x<w;x++){
      var t = (DT_BAYER4[y & 3][x & 3] + 0.5) / 16 * 255;
      out.push(gray[y*w+x] >= t ? 255 : 0);
    }
  }
  return out;
}
function dtFloyd(gray, w, h){
  var buf = gray.slice(), out = new Array(w*h);
  for(var y=0;y<h;y++){
    for(var x=0;x<w;x++){
      var i = y*w + x;
      var old = buf[i], nv = old >= 128 ? 255 : 0;
      out[i] = nv;
      var err = old - nv;
      if(x+1 < w) buf[i+1] += err * 7/16;
      if(y+1 < h){
        if(x > 0) buf[i+w-1] += err * 3/16;
        buf[i+w] += err * 5/16;
        if(x+1 < w) buf[i+w+1] += err * 1/16;
      }
    }
  }
  return out;
}
function dtDemo(size){
  // gradient sphere on gradient background
  var g = [];
  for(var y=0;y<size;y++){
    for(var x=0;x<size;x++){
      var v = (x / (size-1)) * 160;
      var dx = x - size*0.5, dy = y - size*0.45, r = size*0.32;
      var d2 = dx*dx + dy*dy;
      if(d2 < r*r){
        var z = Math.sqrt(r*r - d2);
        var lx = -0.5, ly = -0.6, lz = 0.62;
        var lum = Math.max(0, (dx/r)*lx + (dy/r)*ly + (z/r)*lz);
        v = 40 + lum * 215;
      }
      g.push(v);
    }
  }
  return g;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { DT_BAYER4:DT_BAYER4, dtGray:dtGray, dtThreshold:dtThreshold, dtBayer:dtBayer, dtFloyd:dtFloyd, dtDemo:dtDemo };
}
if (typeof window !== 'undefined') {
  window.DitherForgePure = { DT_BAYER4:DT_BAYER4, dtGray:dtGray, dtThreshold:dtThreshold, dtBayer:dtBayer, dtFloyd:dtFloyd, dtDemo:dtDemo };
}
